// Roda pra cada noiva ativa: calcula o dia dela e filtra quem já terminou os 21 dias
const items = $input.all();
const hoje = new Date();
const resultado = [];

for (const item of items) {
  const lead = item.json;
  const dataCompra = new Date(lead.data_compra || Date.now());
  const diaAtual = Math.floor((hoje - dataCompra) / 86400000) + 1;

  if (diaAtual >= 1 && diaAtual <= 21) {
    const semana = Math.ceil(diaAtual / 7);
    const fases = {
      1: "Semana 1 - Choque Anti-Inchaço: hidratação, água morna com limão, treino leve de ativação.",
      2: "Semana 2 - Intensifica: mais proteína e fibra, circuito mais intenso.",
      3: "Semana 3 - Reta Final: cardápio leve anti-inchaço, tonificação e alongamento, preparação emocional."
    };
    resultado.push({
      json: {
        nome: lead.nome,
        telefone: lead.telefone,
        restricoes: lead.restricoes_alimentares || 'nenhuma',
        dia_atual: diaAtual,
        fase_descricao: fases[semana]
      }
    });
  }
}
return resultado;

